/* Cinematic Studio: centered, handle-based two-frame transitions. All media is local.
 * Frame preparation uses bounded raster samples and never changes timeline or audio timing. */
(function(root){'use strict';
 const FPS=24,BUDGET=96*1024*1024,MAX_SAMPLES=180;
 const catalog=Object.freeze([
 ['crossDissolve','Cross dissolve','Softly blend the outgoing and incoming moving images.'],
 ['dualWipeLeft','Cinematic wipe left','Reveal the incoming image from the right.'],
 ['dualWipeRight','Cinematic wipe right','Reveal the incoming image from the left.'],
 ['dualWipeUp','Cinematic wipe up','Reveal the incoming image from the bottom.'],
 ['dualWipeDown','Cinematic wipe down','Reveal the incoming image from the top.'],
 ['dualIris','Iris reveal','Open a circular aperture over the outgoing frame.'],
 ['dualPushLeft','Push left','Move both images across the frame together.'],
 ['dualPushRight','Push right','Move both images across the frame together.'],
 ['dualZoom','Zoom dissolve','Scale both images with a soft dissolve.'],
 ['dualWhip','Whip pan','Accelerated horizontal push with a brief motion trail.']
 ].map(([id,name,description])=>Object.freeze({id,name,description})));
 const ids=catalog.map(c=>c.id),isType=id=>ids.includes(id);
 const clamp=n=>Math.max(0,Math.min(1,n));
 const boundaryKey=(a,b)=>a.toFixed(5)+':'+b.toFixed(5);
 function plans(parts,items,sourceDuration){
  if(!Number.isFinite(sourceDuration)||sourceDuration<=0)throw Error('Invalid source duration.');
  const result=[];let boundary=0;
  for(let index=1;index<parts.length;index++){
   const a=parts[index-1],b=parts[index];boundary+=a.end-a.start;
   const tr=items.find(x=>isType(x.type)&&boundaryKey(x.fromEnd,x.toStart)===boundaryKey(a.end,b.start));
   if(!tr)continue;
   const duration=Math.min(tr.duration,a.end-a.start,b.end-b.start,2),half=duration/2;
   if(!Number.isFinite(duration)||duration<.08||a.end+half>sourceDuration+.00001||b.start-half<-.00001)
    throw Error('Cut '+index+' needs '+Math.max(.04,half).toFixed(2)+'s of source handles on both sides. Shorten the transition or use a legacy cut treatment.');
   result.push({...tr,index,boundary,duration,half,start:boundary-half,end:boundary+half,count:Math.max(2,Math.ceil(duration*FPS)+1)});
  }
  if(items.some(t=>isType(t.type)&&!result.some(r=>boundaryKey(r.fromEnd,r.toStart)===boundaryKey(t.fromEnd,t.toStart))))throw Error('Cinematic transition has no matching cut.');
  if(result.reduce((n,p)=>n+p.count,0)>MAX_SAMPLES)throw Error('Cinematic preparation limit exceeded. Shorten or remove some two-frame transitions.');
  return result;
 }
 function times(plan,progress,sourceDuration){
  const delta=(clamp(progress)-.5)*plan.duration;
  return {outgoing:Math.max(0,Math.min(sourceDuration-.001,plan.fromEnd+delta)),incoming:Math.max(0,Math.min(sourceDuration-.001,plan.toStart+delta))};
 }
 function dimensions(width,height,ps){
  if(!Number.isFinite(width)||!Number.isFinite(height)||width<1||height<1)throw Error('Video dimensions are unavailable.');
  const frames=ps.reduce((n,p)=>n+p.count*2,0);
  if(!frames)return {width,height,bytes:0};
  const scale=Math.min(1,1920/width,1080/height,Math.sqrt(BUDGET/(4*frames*width*height)));
  const w=Math.max(1,Math.floor(width*scale)),h=Math.max(1,Math.floor(height*scale));
  if(Math.max(w,h)<Math.min(640,Math.max(width,height)))throw Error('Cinematic frame budget exceeded. Reduce transition count or duration.');
  return {width:w,height:h,bytes:4*w*h*frames};
 }
 function ease(t,name){t=clamp(t);if(name==='easeIn')return t*t*t;if(name==='easeOut')return 1-(1-t)**3;
  if(name==='easeInOut')return t<.5?4*t*t*t:1-(-2*t+2)**3/2;if(name==='back')return clamp(1+2.70158*(t-1)**3+1.70158*(t-1)**2);return t;}
 function composite(ctx,a,b,type,progress,w,h,zoom=[],seconds=0,easing='linear',overlay=null,activeFrame=null){
  if(!isType(type)||!a||!b)throw Error('Two decoded frames are required.');
  const p=ease(progress,easing);
  const draw=frame=>{let z={scale:1,x:.5,y:.5};if(root.MangoCreativeZoom)z=root.MangoCreativeZoom.draw(ctx,frame,zoom,seconds,w,h);else ctx.drawImage(frame,0,0,w,h);if(frame===activeFrame)overlay?.(z);};
  function move(frame,x,y,scale=1,alpha=1){ctx.save();try{ctx.globalAlpha=alpha;ctx.translate(x,y);ctx.translate(w/2,h/2);ctx.scale(scale,scale);ctx.translate(-w/2,-h/2);draw(frame);}finally{ctx.restore();}}
  ctx.save();
  try{
   ctx.globalAlpha=1;ctx.globalCompositeOperation='source-over';ctx.fillStyle='#000';ctx.fillRect(0,0,w,h);
   if(p<=0){draw(a);return;}if(p>=1){draw(b);return;}
   if(type==='crossDissolve'){draw(a);move(b,0,0,1,p);return;}
   if(type==='dualZoom'){move(a,0,0,1+.10*p);move(b,0,0,1+.16*(1-p),p);return;}
   if(type==='dualPushLeft'||type==='dualPushRight'||type==='dualWhip'){
    const dir=type==='dualPushRight'?1:-1,q=type==='dualWhip'?p*p*(3-2*p):p;
    move(a,dir*w*q,0);move(b,-dir*w*(1-q),0);
    if(type==='dualWhip'){const trail=Math.sin(Math.PI*q)*.16;move(a,dir*w*q-dir*w*.035,0,1,trail);move(b,-dir*w*(1-q)-dir*w*.035,0,1,trail);}
    return;
   }
   draw(a);ctx.beginPath();
   if(type==='dualIris')ctx.arc(w/2,h/2,Math.hypot(w,h)*p/2,0,Math.PI*2);
   else if(type==='dualWipeLeft')ctx.rect(w*(1-p),0,w*p,h);
   else if(type==='dualWipeRight')ctx.rect(0,0,w*p,h);
   else if(type==='dualWipeUp')ctx.rect(0,h*(1-p),w,h*p);
   else ctx.rect(0,0,w,h*p);
   ctx.clip();draw(b);
  }finally{ctx.restore();}
 }
 function event(video,name,action,signal){
  return new Promise((resolve,reject)=>{
   const cleanup=()=>{clearTimeout(timer);video.removeEventListener(name,done);video.removeEventListener('error',failed);signal?.removeEventListener('abort',aborted);};
   const done=()=>{cleanup();resolve();},failed=()=>{cleanup();reject(Error('Cinematic source decoding failed.'));},aborted=()=>{cleanup();reject(Error('Cinematic preparation cancelled.'));};
   const timer=setTimeout(()=>{cleanup();reject(Error('Cinematic source seek timed out.'));},7000);
   video.addEventListener(name,done,{once:true});video.addEventListener('error',failed,{once:true});signal?.addEventListener('abort',aborted,{once:true});
   if(signal?.aborted){aborted();return;}try{action();}catch(e){cleanup();reject(e);}
  });
 }
 function decoder(url,signal){
  const video=root.document.createElement('video');video.muted=true;video.playsInline=true;video.preload='auto';
  return {video,ready:event(video,'loadeddata',()=>{video.src=url;video.load();},signal),close(){video.pause();video.removeAttribute('src');video.load();}};
 }
 async function frame(v,time,w,h,signal){
  if(signal?.aborted)throw Error('Cinematic preparation cancelled.');
  if(Math.abs(v.currentTime-time)>.0001||v.seeking)await event(v,'seeked',()=>{v.currentTime=time;},signal);
  if(v.readyState<2)throw Error('Decoded frame unavailable.');
  const canvas=root.document.createElement('canvas');canvas.width=w;canvas.height=h;canvas.getContext('2d',{alpha:false}).drawImage(v,0,0,w,h);
  return canvas;
 }
 function createCache(){
  let key=null,entries=new Map(),promise=null,controller=null,error=null,quality=null;
  const signature=(url,duration,parts,items)=>JSON.stringify([url,duration,parts,items.filter(t=>isType(t.type))]);
  function clear(){controller?.abort();controller=null;for(const list of entries.values())for(const pair of list){pair.a.width=0;pair.b.width=0;}entries.clear();key=null;promise=null;error=null;quality=null;}
  function prepare(url,duration,parts,items,width,height,notify=()=>{}){
   const wanted=signature(url,duration,parts,items);
   if(key===wanted){if(error)return Promise.reject(error);if(promise)return promise;return Promise.resolve(quality);}
   clear();key=wanted;
   let ps,dim;try{ps=plans(parts,items,duration);dim=dimensions(width,height,ps);}catch(e){error=e;return Promise.reject(e);}
   quality={...dim,fps:FPS,transitions:ps.length};
   if(!ps.length)return Promise.resolve(quality);
   controller=new AbortController();const signal=controller.signal,local=new Map();
   promise=(async()=>{
    const left=decoder(url,signal),right=decoder(url,signal);let done=0;const total=ps.reduce((n,p)=>n+p.count,0);
    try{
     await Promise.all([left.ready,right.ready]);
     for(const p of ps){const list=[];local.set(p.index,list);
      for(let i=0;i<p.count;i++){
       const t=times(p,i/(p.count-1),duration),pair=await Promise.all([frame(left.video,t.outgoing,dim.width,dim.height,signal),frame(right.video,t.incoming,dim.width,dim.height,signal)]);
       if(signal.aborted){pair[0].width=0;pair[1].width=0;throw Error('Cinematic preparation cancelled.');}
       list.push({a:pair[0],b:pair[1]});notify(++done,total);
      }
     }
     if(signal.aborted||key!==wanted)throw Error('Cinematic preparation cancelled.');
     entries=local;return quality;
    }catch(e){for(const list of local.values())for(const pair of list){pair.a.width=0;pair.b.width=0;}if(key===wanted)error=e;throw e;}
    finally{left.close();right.close();if(key===wanted){promise=null;controller=null;}}
   })();
   return promise;
  }
  function ready(url,duration,parts,items){return key===signature(url,duration,parts,items)&&!promise&&!error&&!!quality;}
  function paint(ctx,url,duration,parts,items,t,w,h,zoom=[],overlay=null){
   const active=root.MangoMotion.transitionAt(parts,items,t);
   if(!active||!isType(active.type))return false;
   if(!ready(url,duration,parts,items))return false;
   const samples=entries.get(active.index);if(!samples?.length)return false;
   const p=samples[Math.min(samples.length-1,Math.max(0,Math.round(active.progress*(samples.length-1))))];
   composite(ctx,p.a,p.b,active.type,active.progress,w,h,zoom,t,active.ease,overlay,t<active.boundary?p.a:p.b);return true;
  }
  return {prepare,ready,paint,clear};
 }
 async function exact(ctx,url,duration,parts,items,t,w,h,zoom=[],signal){
  const active=root.MangoMotion.transitionAt(parts,items,t);if(!active||!isType(active.type))return false;
  const p=plans(parts,items,duration).find(x=>x.index===active.index);if(!p)throw Error('Transition cut unavailable.');
  const left=decoder(url,signal),right=decoder(url,signal);
  try{await Promise.all([left.ready,right.ready]);const at=times(p,active.progress,duration),[a,b]=await Promise.all([frame(left.video,at.outgoing,w,h,signal),frame(right.video,at.incoming,w,h,signal)]);try{composite(ctx,a,b,p.type,active.progress,w,h,zoom,t,p.ease);}finally{a.width=0;b.width=0;}return true;}
  finally{left.close();right.close();}
 }
 const api=Object.freeze({FPS,BUDGET,MAX_SAMPLES,catalog,ids,isType,plans,times,dimensions,ease,composite,createCache,exact});
 root.MangoCinematicV0713=api;if(typeof module==='object'&&module.exports)module.exports=api;
})(typeof globalThis!=='undefined'?globalThis:this);

/* Clean-master reconstruction: bounded, deterministic import into existing
 * camera and cursor-effect editing models. Never attempts to remove baked pixels. */
(function(root){'use strict';
 const MIN=.05,MAX_ZOOM=5,MAX_KEYS=240,MAX_REGIONS=120,EPS=1e-6;
 const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),round=(v,d=1000000)=>Math.round(v*d)/d;
 const neutral=()=>({t:0,z:1,tx:0,ty:0});
 const isLive=id=>typeof id==='string'&&id.startsWith('live-capture-');
 const near=(a,b)=>Math.max(Math.abs(a.z-b.z),Math.abs(a.tx-b.tx),Math.abs(a.ty-b.ty));
 function point(s){const [t,z,cx,cy,fx,fy,fw,fh]=s;return {t,z,tx:fx*(1-z)+fw*(.5-z*cx),ty:fy*(1-z)+fh*(.5-z*cy)};}
 function anchor(p){return p.z<=1+EPS?{scale:1,x:.5,y:.5}:{scale:clamp(p.z,1,MAX_ZOOM),x:clamp(-p.tx/(p.z-1),0,1),y:clamp(-p.ty/(p.z-1),0,1)};}
 function lerp(a,b,t){const f=clamp((t-a.t)/Math.max(EPS,b.t-a.t),0,1);return {t,z:a.z+(b.z-a.z)*f,tx:a.tx+(b.tx-a.tx)*f,ty:a.ty+(b.ty-a.ty)*f};}
 function compact(points,tolerance){if(points.length<3)return points;const keep=new Set([0,points.length-1]),stack=[[0,points.length-1]];
  while(stack.length){const [a,b]=stack.pop();let best=tolerance,index=-1;for(let i=a+1;i<b;i++){const error=near(points[i],lerp(points[a],points[b],points[i].t));if(error>best){best=error;index=i;}}if(index>=0){keep.add(index);if(keep.size>MAX_KEYS*4)return null;stack.push([a,index],[index,b]);}}
  return [...keep].sort((a,b)=>a-b).map(i=>points[i]);
 }
 function camera(frames,duration){
  const source=(frames||[]).filter(s=>s[0]<=duration);if(!source.some(s=>s[1]>1.0001))return {items:[],notice:''};
  if(source.some(s=>s[1]>MAX_ZOOM+.0001))return {items:[],notice:'Captured zoom exceeds the editor limit; camera history retained without automatic reconstruction.'};
  if(source.some(s=>s[1]>1.0001&&(Math.abs(s[4])>.001||Math.abs(s[5])>.001||Math.abs(s[6]-1)>.001||Math.abs(s[7]-1)>.001)))return {items:[],notice:'Zoomed letterboxed frames require crop-aware reconstruction; camera history retained.'};
  if(source[0][0]>.55||source.some((s,i)=>i&&s[0]-source[i-1][0]>.55)||duration-source.at(-1)[0]>.75)return {items:[],notice:'Camera samples contain gaps; history retained without automatic reconstruction.'};
  // Preserve neutral at the start, unless the first capture already contains a zoom.
  let points=[neutral()];for(const s of source){const p=point(s);if(p.t<MIN){if(points.length===1&&p.z>1.0001)points.push({...p,t:MIN});continue;}if(p.t-points.at(-1).t>=MIN-EPS)points.push(p);else if(near(p,points.at(-1))>EPS&&p.t===source.at(-1)[0]&&points.length>1){const prev=points.at(-2);if(p.t-prev.t>=MIN-EPS)points[points.length-1]=p;}}
  if(points.length<2)return {items:[],notice:'Recording too short to reconstruct camera motion.'};
  const reduced=compact(points,.006);if(!reduced)return {items:[],notice:'Camera path exceeds the editable keyframe budget; history retained.'};
  const items=[];let i=0;
  for(let n=1;n<reduced.length;n++){const a=reduced[n-1],b=reduced[n],delta=b.t-a.t;if(near(a,b)<EPS)continue;if(delta<MIN-EPS)continue;
   const pieces=Math.ceil(delta/5);for(let k=1;k<=pieces;k++){const begin=a.t+delta*(k-1)/pieces,end=a.t+delta*k/pieces,p=lerp(a,b,end);const start=round(begin),length=round(end)-start;if(length<MIN-EPS||start>=duration)continue;
    items.push({id:'live-camera-'+(++i),start,duration:round(length),...anchor(p),ease:'linear'});if(items.length>MAX_KEYS)return {items:[],notice:'Camera path exceeds 240 editable events; history retained.'};}}
  return {items,notice:items.length?'Camera reconstructed from sampled motion (approximate).':''};
 }
 function effects(states,duration){
  const list=[];for(let i=0;i<(states||[]).length;i++){const s=states[i],v=s[3],start=clamp(s[0],0,duration),end=clamp(states[i+1]?.[0]??duration,0,duration);if(!v||!v.spotlight&&!v.ring||end-start<.03999)continue;
   const style={spotlight:v.spotlight,ring:v.ring,pulse:v.ring,marker:'none',radius:v.radius,dim:v.dim,feather:v.feather,color:v.color,smooth:0,markerSize:1};
   const previous=list.at(-1);if(previous&&Math.abs(previous.end-start)<EPS&&JSON.stringify(previous.style)===JSON.stringify(style))previous.end=end;
   else list.push({id:'live-capture-'+list.length,start,end,enabled:true,style});
   if(list.length>MAX_REGIONS)return {items:[],notice:'Live effect settings exceed 120 regions; history retained without automatic reconstruction.'};
  }return {items:list,notice:''};
 }
 function rebuild(trace,duration){if(!Number.isFinite(duration)||duration<=0||duration>86400)throw Error('Invalid clean master duration');
  const meta=trace?.capture;if(trace?.baked||meta?.master!=='clean')throw Error('A clean master with compatible capture telemetry is required.');
  if(trace.truncated||meta.truncated)return {zoomFrames:[],regions:[],notices:['Capture telemetry is truncated; automatic reconstruction withheld.']};
  const z=meta.states.at(-1)?.[1]==='off'?{items:[],notice:'Capture retention ended; camera history retained without extrapolating motion.'}:camera(meta.cameraFrames,duration),fx=effects(meta.states,duration);
  return {zoomFrames:z.items,regions:fx.items,notices:[z.notice,fx.notice].filter(Boolean)};
 }
 const api=Object.freeze({isLive,camera,effects,rebuild});root.MangoCleanMasterV0752=api;if(typeof module==='object'&&module.exports)module.exports=api;
})(typeof globalThis!=='undefined'?globalThis:this);

/* Local Media Bin: staged references are inert until prepared and applied in Multitrack Studio. */
(function(root){
 'use strict';
 const el=id=>document.getElementById(id),view=()=>root.MangoClipView;
 if(!el('v06-media-input')||!root.MangoMediaAssets||!root.MangoProjectV2)return;
 const registry=root.MangoMediaAssets.create(),notes=el('v06-media-note');
 let selected=null,loadedProject=null,staged=[];
 const fmt=n=>Number.isFinite(n)?n.toFixed(2)+'s':'not decoded';
 const label=text=>{notes.textContent=text;};
 const clean=node=>node.replaceChildren();
 const span=(text,cls='')=>{const n=document.createElement('span');n.textContent=text;n.className=cls;return n;};
 const button=(name,onClick)=>{const n=document.createElement('button');n.type='button';n.textContent=name;n.addEventListener('click',onClick);return n;};
 const filesize=n=>n>=1048576?(n/1048576).toFixed(1)+' MiB':Math.ceil(n/1024)+' KiB';
 const kindMark={image:'▧',video:'▶',audio:'♫'};
 function updateControls(){const a=registry.get(selected),st=el('v06-stage-asset');
  st.disabled=!a||a.missing||(a.kind!=='image'&&!Number.isFinite(a.duration));
  el('v06-relink-asset').disabled=!a||!a.missing;
  el('v06-remove-asset').disabled=!a||a.id==='source-primary'||!!view()?.secondaryReferences?.(a.id)||!!view()?.exporting?.();
  el('v06-restore-project').disabled=!loadedProject?.legacyV1;
  el('v06-save-project').disabled=!view()?.original()||!!view()?.exporting?.();
 }
 function preview(a){const container=el('v06-asset-preview');clean(container);
  if(!a){container.textContent='Select a local image, video or audio file to inspect it.';return;}
  const title=document.createElement('strong');title.textContent=a.name;container.append(title);
  const meta=span(`${a.kind.toUpperCase()} · ${filesize(a.size)}${a.duration!=null?' · '+fmt(a.duration):''}`,'v06-meta');container.append(meta);
  if(a.missing||!a.url){container.append(span('Source file missing — choose Relink file.','v06-warning'));return;}
  const media=document.createElement(a.kind==='image'?'img':a.kind==='video'?'video':'audio');
  media.className='v06-preview-media';media.src=a.url;
  if(a.kind==='image'){media.alt='Preview of '+a.name;media.addEventListener('load',()=>{
    try{registry.updateMeta(a.id,{width:media.naturalWidth,height:media.naturalHeight});}catch{}});}
  else {media.controls=true;media.preload='metadata';media.addEventListener('loadedmetadata',()=>{
    try{const props={};if(Number.isFinite(media.duration)&&media.duration>0)props.duration=media.duration;
      if(a.kind==='video'){props.width=media.videoWidth||null;props.height=media.videoHeight||null;}
      registry.updateMeta(a.id,props);
    }catch(error){label('Could not read media metadata: '+error.message);}updateControls();
  });}
  container.append(media);
 }
 // Editing decisions change often, but imported assets rarely do. Avoid
 // reconstructing the asset DOM on every timeline refresh or playhead change.
 let lastAssetSignature=null;
 function draw(){
  const assets=registry.snapshot();
  const stamp=assets.map(a=>[a.id,a.name,a.kind,a.size,a.missing,a.duration,a.width,a.height].join('|')).join('~')+
   '::'+selected+'::'+JSON.stringify(view()?.multitrack?.()||{})+'::'+staged.map(c=>[c.id,c.assetId,c.track,c.start,c.end].join('|')).join('~');
  updateControls();
  if(stamp===lastAssetSignature)return;
  lastAssetSignature=stamp;
  const list=el('v06-asset-list');clean(list);
  for(const a of assets){
   const item=button('',()=>{selected=a.id;preview(registry.get(a.id));draw();});
   item.className='v06-asset'+(a.id===selected?' is-selected':'');item.setAttribute('aria-pressed',String(a.id===selected));
   item.title=a.name;item.append(span(kindMark[a.kind]||'□','v06-kind'),span(a.name,'v06-filename'),span(a.missing?'Relink':filesize(a.size),'v06-small'));
   list.append(item);
  }
  if(!registry.count())list.append(span('No media imported. Choose + Media to begin.','v06-hint'));
  const drafts=el('v06-staged-list');clean(drafts);
  for(const c of staged){const a=registry.get(c.assetId);
   const row=document.createElement('div');row.className='v06-staged-row';
   row.append(span(`${c.track} · ${a?.name||'Missing asset'} · ${fmt(c.start)} – ${fmt(c.end)}`));
   row.append(button('Remove',()=>{staged=staged.filter(x=>x.id!==c.id);draw();}));drafts.append(row);
  }
  for(const c of view()?.multitrack?.().clips||[]){const a=registry.get(c.assetId),r=document.createElement('div');r.className='v06-staged-row';r.append(span('ACTIVE · '+c.track+' · '+(a?.name||'Missing asset')+' · '+fmt(c.start)+'–'+fmt(c.end)),button('Edit',()=>root.MangoMultitrackUIV0716?.open()));drafts.append(r);}
  if(!staged.length&&!view()?.multitrack?.().clips.length)drafts.append(span('No secondary clips.','v06-hint'));
  el('v06-count').textContent=assets.length+' assets · '+(view()?.multitrack?.().clips.length||0)+' active · '+staged.length+' staged';
 }
 registry.subscribe(()=>{draw();const a=registry.get(selected);if(a){const target=el('v06-asset-preview');
  if(target?.querySelector('strong')?.textContent!==a.name)preview(a);} });
 async function addFiles(files){let added=0,errors=[];
  for(const file of [...files].slice(0,200)){
   try{const result=registry.register(file);if(!result.duplicate)added++;selected=result.asset.id;}
   catch(e){errors.push(file.name+': '+e.message);}
  }
  if(selected)preview(registry.get(selected));draw();
  label(`${added} local asset(s) imported.${errors.length?' '+errors.slice(0,2).join('; '):''} Open Multitrack Studio to prepare and apply media.`);
 }
 el('v06-media-input').addEventListener('change',event=>{void addFiles(event.target.files||[]);event.target.value='';});
 el('v06-relink-input').addEventListener('change',event=>{const file=event.target.files?.[0];event.target.value='';if(!file||!selected)return;
  try{registry.relink(selected,file);preview(registry.get(selected));label('Local file relinked.');}
